/** @jest-environment node */

const {
  detectMfeNamespace,
  isSharedComponentsKey,
  mergeSharedUnderMfeNamespace,
  normalizeFlatKey,
  SHARED_COMPONENTS_PREFIX,
} = require('../mergeSharedUnderMfeNamespace');

describe('mergeSharedUnderMfeNamespace', () => {
  it('detects MFE namespace from MFE flat keys', () => {
    expect(
      detectMfeNamespace({
        'hub-analytics.homePage.title': 'Analytics Home',
      })
    ).toBe('hub-analytics');
  });

  it('returns null when MFE entries are empty', () => {
    expect(detectMfeNamespace({})).toBeNull();
  });

  it('warns and uses first namespace when multiple MFE namespaces exist', () => {
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    expect(
      detectMfeNamespace({
        'hub-a.key': '1',
        'hub-b.key': '2',
      })
    ).toBe('hub-a');

    expect(warnSpy).toHaveBeenCalledWith(
      expect.stringContaining('Multiple MFE namespaces found (hub-a, hub-b)')
    );
    warnSpy.mockRestore();
  });

  it('nests shared entries under the MFE namespace', () => {
    const result = mergeSharedUnderMfeNamespace(
      {
        'hub-analytics.homePage.title': 'Analytics Home',
      },
      {
        'SurveyModal.JourneyModal.title': 'How was your experience?',
      }
    );

    expect(result).toEqual({
      'hub-analytics.homePage.title': 'Analytics Home',
      'hub-analytics.SurveyModal.JourneyModal.title': 'How was your experience?',
    });
  });

  it('returns empty object when both MFE and shared entries are empty', () => {
    expect(mergeSharedUnderMfeNamespace({}, {})).toEqual({});
  });

  it('includes shared entries at root level when no MFE namespace is detected', () => {
    const warnSpy = jest.spyOn(console, 'warn').mockImplementation(() => {});

    const result = mergeSharedUnderMfeNamespace(
      {},
      {
        'SurveyModal.title': 'Survey',
      }
    );

    expect(result).toEqual({
      'SurveyModal.title': 'Survey',
    });
    expect(warnSpy).toHaveBeenCalledWith(
      '⚠️  No MFE namespace detected; shared entries included at root level'
    );
    warnSpy.mockRestore();
  });

  it('uses shared value when a shared key collides with an existing MFE key', () => {
    const result = mergeSharedUnderMfeNamespace(
      {
        'hub-analytics.SurveyModal.title': 'Existing',
      },
      {
        'SurveyModal.title': 'Shared',
      }
    );

    expect(result['hub-analytics.SurveyModal.title']).toBe('Shared');
  });

  it('identifies shared-components keys and normalizes them', () => {
    expect(SHARED_COMPONENTS_PREFIX).toBe('shared-components.');
    expect(isSharedComponentsKey('shared-components.SurveyModal.title')).toBe(true);
    expect(isSharedComponentsKey('hub-analytics.homePage.title')).toBe(false);
    expect(normalizeFlatKey('shared-components.SurveyModal.title')).toBe('SurveyModal.title');
    expect(normalizeFlatKey('hub-analytics.homePage.title')).toBe('hub-analytics.homePage.title');
  });
});
